UPDATE orders.orders
SET status         = #{status},
    items          = #{items},
    total_amount   = #{totalAmount},
    customer_id    = #{customerId},
    tracking_number = #{trackingNumber},
    cancel_reason  = #{cancelReason},
    version        = version + 1,
    update_at      = #{updateAt}

    , updated_by = #{updatedBy}

WHERE id = #{id}
  AND version = #{version}
  AND is_delete = false

UPDATE orders.orders
SET is_delete = true,
    update_at = #{now}

    , updated_by = #{updatedBy}

WHERE id = #{id}
  AND is_delete = false

